out = minimize(&fct, x0, ..., ctl)

// Rosenbrock function
    proc (1) = rosenbrock(x);
        retp((1 - x[1])^2 + 100*(x[2] - x[1]^2)^2);
    endp;

    // Starting point
    x0 = { -1, 1 };

    // Minimize
    struct minimizeOut out;
    out = minimize(&rosenbrock, x0);

    print "Solution: " out.x';
    print "Objective: " out.fval;

